return [{ json: {
  "campaign": "Shuttle fund (fictional)",
  "goalCents": 600000,
  "proposedReceivedCents": 600000,
  "records": [
    {
      "id": "D-101",
      "source": "deposit log",
      "status": "posted",
      "cents": 180000
    },
    {
      "id": "D-102",
      "source": "deposit log",
      "status": "posted",
      "cents": 240000
    },
    {
      "id": "P-201",
      "source": "pledge register",
      "status": "signed",
      "cents": 180000
    }
  ]
} }];

const input = $input.first().json;
const issues = [];
const seen = new Map();
const trace = [];
const duplicates = [];
let received = 0;
let pledged = 0;
for (const row of input.records ?? []) {
  const id = row.id;
  if (typeof id !== 'string' || !id.trim() || !Number.isSafeInteger(row.cents) || row.cents <= 0) {
    issues.push('Invalid source ID or positive whole-cent amount');
    continue;
  }
  const fingerprint = JSON.stringify([row.source, row.status, row.cents]);
  if (seen.has(id)) {
    if (seen.get(id) !== fingerprint) issues.push('Conflicting versions of ' + id);
    else duplicates.push(id);
    continue;
  }
  seen.set(id, fingerprint);
  let bucket;
  if (row.source === 'deposit log' && row.status === 'posted') {
    bucket = 'received';
    received += row.cents;
  } else if (row.source === 'pledge register' && row.status === 'signed') {
    bucket = 'pledged';
    pledged += row.cents;
  } else {
    issues.push('Unrecognized source or status for ' + id);
    continue;
  }
  trace.push({ id, source: row.source, status: row.status, cents: row.cents, bucket });
}
if (!trace.length) issues.push('No usable records');
if (!Number.isSafeInteger(input.goalCents) || input.goalCents <= 0 ||
    !Number.isSafeInteger(input.proposedReceivedCents) || input.proposedReceivedCents < 0 ||
    !Number.isSafeInteger(received) || !Number.isSafeInteger(pledged)) {
  issues.push('Invalid goal, proposed amount or total');
}
const common = {campaign: input.campaign, trace, duplicates, issues};
if (issues.length) return [{json: {...common, status:'REVIEW', draft:null}}];
const currency = n => (n / 100).toLocaleString('en-US', {style:'currency',currency:'USD',minimumFractionDigits:0,maximumFractionDigits:2});
return [{json: {...common, status:'READY FOR REVIEW', receivedCents:received,
 pledgedCents:pledged, goalCents:input.goalCents, claimedExcessCents:input.proposedReceivedCents-received,
 percentReceived:Math.round(1000*received/input.goalCents)/10,
 draft:input.campaign+' received '+currency(received)+' toward its '+currency(input.goalCents)+' goal. Signed pledges total '+currency(pledged)+'.'}}];
